function auditDeferEagleVision(runtime: Runtime, retained: Set<ActiveEffect>): void {
  for (const list of [runtime.usedEffects, runtime.primaryUsedEffects]) {
    for (let index = list.length - 1; index >= 0; index--) {
      const effect = list[index];
      if ((effect.source.effectId ?? effect.intent.id) !== "EagleVision/1") continue;
      if (effect.triggerEffects?.length) throw new Error("Unspecified EagleVision child timing");
      retained.add(effect);
      list.splice(index, 1);
    }
  }
}

